bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 60
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'JS'
import pg from 'pg';import {readFileSync} from 'node:fs';
const e=process.env,db=new pg.Pool({host:e.VIDEOBOT_DB_HOST,user:e.VIDEOBOT_DB_USER,database:e.VIDEOBOT_DB_NAME,password:readFileSync('/run/secrets/videobot_db_password','utf8').trim(),max:1,connectionTimeoutMillis:5000});
try{
 const q=await db.query("SELECT a.revision old_rev,a.status old_status,a.free_message_ids old_free,a.paid_message_id old_paid,b.revision current_rev,b.status current_status,b.free_message_ids current_free,b.paid_message_id current_paid,b.topic_id current_topic FROM videobot_post_receipts a JOIN videobot_listings l ON l.listing_id=a.listing_id JOIN videobot_post_receipts b ON b.listing_id=l.listing_id AND b.revision=l.revision WHERE a.paid_message_id=4691 AND a.free_message_ids=ARRAY[4689,4690]::bigint[]");
 if(q.rowCount!==1)process.exit(61);
 const r=q.rows[0];
 if(r.current_status!=='sent'||!Array.isArray(r.current_free)||r.current_free.length!==2||!r.current_paid)process.exit(62);
 if(Number(r.current_rev)!==Number(r.old_rev) && String(r.current_free)===String(r.old_free))process.exit(63);
 if(Number(r.current_rev)===Number(r.old_rev))process.exit(64);
 if(r.old_status==='sent')process.exit(85);
 if(r.old_status==='needs_reconcile')process.exit(86);
 process.exit(87);
}catch{process.exitCode=70}finally{await db.end()}
JS
